WITH exploded AS (SELECT id, plan, effective_from, EXPLODE(tier_prices) AS element FROM price_tiers) SELECT *, RANK() OVER (PARTITION BY plan ORDER BY element) element_rank, CUME_DIST() OVER (PARTITION BY plan ORDER BY element DESC) element_cume_dist, CUME_DIST() OVER (ORDER BY element DESC) element_cume_dist_2, MIN(element) OVER (PARTITION BY plan) plan_min_element, RANK() OVER (PARTITION BY plan ORDER BY element DESC NULLS LAST) element_rank_2 FROM exploded;
